import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';

export default function HomeView() {
  const [inputCode, setInputCode] = useState('');
  const navigate = useNavigate();

  const handleNumberClick = (num) => {
    setInputCode(prev => prev + num);
  };

  const handleClear = () => {
    setInputCode('');
  };

  const handleEnter = () => {
    const users = JSON.parse(localStorage.getItem('faceUsers') || '[]');
    const userExists = users.find(user => user.userId === inputCode);
    if (userExists) {
      sessionStorage.setItem('loginUserId', inputCode);
      navigate('/login');
    } else {
      alert('User ID not found');
    }
  };

  const renderButtons = () => {
    const numbers = [...Array(10).keys()];
    return numbers.map(n => (
      <button
        key={n}
        onClick={() => handleNumberClick(n.toString())}
        className="btn btn-outline-dark m-1"
      >
        {n}
      </button>
    ));
  };

  return (
    <div className="container text-center py-5">
      <h1 className="mb-4">🔐 Bienvenido a Face Auth</h1>

      <div className="mb-4">
        <Link to="/register">
          <button className="btn btn-warning mx-2">Registrar Usuario</button>
        </Link>
        <Link to="/users">
          <button className="btn btn-secondary">Ver Usuarios</button>
        </Link>
        <Link to="/settings">
          <button className="btn btn-r">Configuracion</button>
        </Link>
      </div>

      <div className="mb-4">
        <p className="fw-semibold">Ingresar Codigo:</p>
        <div className="border border-secondary rounded py-2 px-3 fs-4 d-inline-block mb-3 bg-light">
          {inputCode || '• • • •'}
        </div>

        <div className="d-flex flex-wrap justify-content-center mb-3">
          {renderButtons()}
        </div>

        <div>
          <button onClick={handleClear} className="btn btn-danger mx-2">Borrar</button>
          <button onClick={handleEnter} className="btn btn-success">Ingresar</button>
        </div>
      </div>
    </div>
  );
}
