import React, { useRef, useEffect, useState } from 'react';
import * as faceapi from 'face-api.js';
import { Link } from 'react-router-dom';

export default function RegisterView() {
  const videoRef = useRef();
  const [userId, setUserId] = useState('');
  const [modelsLoaded, setModelsLoaded] = useState(false);

  useEffect(() => {
    const loadModels = async () => {
      await faceapi.nets.ssdMobilenetv1.loadFromUri('/models');
      await faceapi.nets.faceRecognitionNet.loadFromUri('/models');
      await faceapi.nets.faceLandmark68Net.loadFromUri('/models');
      setModelsLoaded(true);
      console.log('✅ Models loaded');
    };
    loadModels();
  }, []);

  const startCamera = () => {
    navigator.mediaDevices.getUserMedia({ video: {} })
      .then(stream => {
        videoRef.current.srcObject = stream;
      });
  };

  const registerFace = async () => {

    if (!userId.trim()) {
      alert('Ingresa un unico ID antes de registrar');
      return;
    }
   if (!modelsLoaded) {
      return alert('⏳ Please wait, models are still loading...');
    }
    const detection = await faceapi
    .detectSingleFace(videoRef.current, new faceapi.SsdMobilenetv1Options())
    .withFaceLandmarks()
    .withFaceDescriptor();

    
    if (!detection || !detection.detection?.box || detection.detection.box.top === null || detection.detection.box.bottom === null) {
      return alert('⚠️ Face detection failed, please try again with better lighting or position.');
    }
    const faceId = Array.from(detection.descriptor);
    const registeredAt = new Date().toLocaleString();
    const user = { userId, faceId, registeredAt };
    const users = JSON.parse(localStorage.getItem('faceUsers') || '[]');
    users.push(user);
    localStorage.setItem('faceUsers', JSON.stringify(users));
    alert('User registered successfully');
  };

  return (
    <div className="p-4">
      <h1 className="text-xl font-bold">Registrar</h1>

      <Link to="/">
        <button className="btn btn-warning px-4 py-2 my-2"> Inicio</button>
       
      </Link>
      <Link to="/users">
        <button className="btn btn-secondary  px-4 py-2 my-2 ml-2">Ver Usuarios</button>
      </Link>

      
      <input className="border p-2 my-2 block" value={userId} onChange={e => setUserId(e.target.value)} placeholder="User ID" />
      <video ref={videoRef} autoPlay muted width="320" height="240" className="my-2" />
      {!modelsLoaded && (
  <p className="text-red-500 mb-2">⏳ Loading models, please wait...</p>
)}
      
      <button onClick={startCamera} className="btn btn-warning px-4 py-2 my-2">Encender Camara</button>
      <button onClick={registerFace} className="btn btn-secondary  px-4 py-2 my-2 ml-2">Registrar</button>
    </div>
  );
}